"""P211 terminal-build recorder primitives; source-only preparation.

Explicitly adapted from actual p211_initial_build_01/outer/executed_adapter
build_core.py, not an independent implementation or a new scientific check.
Native settlement, stream, FLS and seal semantics are preserved. No current
execution is authorized; each future actual build requires a root binding.
"""
import hashlib
import json
import locale
import os
from pathlib import Path
import re
